mapper.update:
UPDATE theme.sp_municipality
   SET area_km2 = round((ST_Area(geom::geography) / 1e6)::numeric, 3),
       centroid = coalesce(centroid, theme.inner_point(geom));
UPDATE theme.sp_district SET area_km2 = round((ST_Area(geom::geography) / 1e6)::numeric, 3);
UPDATE theme.sp_community SET area_km2 = round((ST_Area(geom::geography) / 1e6)::numeric, 3)

UPDATE theme.meta_table
   SET row_count = #{rows}, source_as_of = #{asOf}, loaded_at = now()
 WHERE table_name = #{table}
